const capability={version:2,stages:[{id:"stage_1",io:{"reads":{"input":["rank"],"state":[]},"writes":{"state":["targets.__actedOn"],"output":[]}},navigation:"optional",async run({input,waitForTarget,waitUntil,settle}){const rank=input["rank"];const cssSelector=`#current-hotlist > div:nth-of-type(2) > div:nth-of-type(3) > div > div:nth-of-type(${rank}) > div`;const element=await waitForTarget({strategies:[{type:"css",value:cssSelector}]});const actedOn=(element.innerText||element.textContent||"").replace(/\s+/gu," ").trim().slice(0,240);const hrefBefore=location.href;const textBefore=document.body.innerText;element.click();await waitUntil(()=>location.href!==hrefBefore||document.body.innerText!==textBefore);await settle();return{outcome:"Continue",state:{targets:{__actedOn:actedOn}}}}},{id:"stage_verify",io:{"reads":{"input":["rank"],"state":["targets.__actedOn"]},"writes":{"state":[],"output":["currentRank","targetTitle","targetUrl"]}},navigation:"none",async run({input,state,waitUntil,settle,identityMatches}){const actedOn=state.targets?.__actedOn;await waitUntil(()=>{const headlineBtn2=document.querySelector("#current-hotlist > div:nth-of-type(2) > div:nth-of-type(3) > section > button");if(headlineBtn2){const text=headlineBtn2.innerText;return text&&text.length>10}return location.search.includes("?topic=")});await settle();let targetTitle="";let targetUrl="";let currentRank=input["rank"];const headlineBtn=document.querySelector("#current-hotlist > div:nth-of-type(2) > div:nth-of-type(3) > section > button");if(headlineBtn){const fullText=headlineBtn.innerText;const container=document.querySelector("#current-hotlist > div:nth-of-type(2) > div:nth-of-type(3) > div");if(container){const rankItem=container.querySelector(`div:nth-of-type(${input["rank"]})`);if(rankItem){const itemText=rankItem.innerText;const lines=itemText.split("\n").map(l=>l.trim()).filter(l=>l);if(lines.length>=2){targetTitle=lines[1]}}}}if(!targetTitle&&headlineBtn){const fullText=headlineBtn.innerText;const lines=fullText.split("\n").map(l=>l.trim()).filter(l=>l);if(lines.length>=2){const startIndex=lines[0]==="\u5934\u6761"?1:0;if(lines[startIndex]){targetTitle=lines[startIndex]}}}if(location.search.includes("?topic=")){targetUrl=location.href}else{const topicLink=document.querySelector('a[href*="?topic="]');if(topicLink){targetUrl=topicLink.href}else{targetUrl=`https://www.example.test/?topic=${encodeURIComponent(targetTitle)}`}}if(actedOn&&targetTitle){if(!identityMatches(actedOn,targetTitle)){const parts=actedOn.split(/\s+/);if(parts.length>=2){targetTitle=parts.slice(1).find(p=>p&&!/^\d/.test(p))||parts[1]}}}if(!targetTitle){return{outcome:"NoResult",reason:"Could not extract topic title from page"}}if(!targetUrl||!targetUrl.startsWith("http")){return{outcome:"NoResult",reason:"Could not extract valid topic URL"}}return{outcome:"Success",output:{targetTitle,targetUrl,currentRank},evidence:[{kind:"status",value:{url:location.href,title:targetTitle}}]}}}]};export{capability};